final class LegateProviderInvocationAndCognitionTurnTest extends TestCase
{
 public function testActivatesOpaqueLeaseThenConsumesExactlyOneCognitionTurn():void{$root=sys_get_temp_dir().'/imperium-citadel-turn-'.bin2hex(random_bytes(5));try{[$decision,$authority,$locksmith]=$this->fixtures($root,'2026-08-23T20:10:00+00:00');$at=new \DateTimeImmutable('2026-08-23T20:01:00+00:00');$activation=(new LegateProviderInvocationActivationService($root))->activate($decision,$authority,$locksmith,$at);self::assertSame('CITADEL_LEGATE_PROVIDER_INVOCATION_ACTIVATED_PENDING_ONE_BOUNDED_COGNITION_TURN',$activation['status']);self::assertTrue($activation['provider_invocation_authority']);self::assertTrue($activation['credential_use_authority']);self::assertFalse($activation['credential_lease']['credential_reference_disclosed']);self::assertFalse($activation['credential_lease']['credential_possession_transferred']);self::assertArrayNotHasKey('credential_ref',$activation['credential_lease']);self::assertFalse($activation['provider_invoked']);
 $gateway=new class implements LegateCognitionGateway{public function cognize(array$a):array{return['disposition'=>'COMPLETED','output'=>'One bounded recommendation.','evidence_references'=>['sealed-input-digest'],'uncertainties'=>['No external evidence was authorized.'],'stop_condition_triggered'=>false,'stop_rationale'=>'The exact internal response is complete.'];}};$service=new LegateBoundedCognitionTurnService($root,$gateway);$turn=$service->perform($activation['activation_id'],$at->modify('+1 minute'));self::assertSame('CITADEL_LEGATE_GOVERNED_COGNITION_TURN_COMPLETED_SEALED_NO_CONTINUING_AUTHORITY',$turn['status']);self::assertTrue($turn['provider_invoked']);self::assertTrue($turn['cognition_performed']);self::assertSame(1,$turn['turns_consumed']);self::assertTrue($turn['bounded_cognition_turn_authority']['consumed']);self::assertTrue($turn['credential_lease']['consumed']);foreach(['commission_exercisable','governed_cognition_authority','provider_invocation_authority','credential_use_authority','operational_use_permitted','autonomous_cognition_authority','tool_use_authority','tools_used','external_action_authority','external_action_performed','execution_authority','continuing_turn_authority']as$f)self::assertFalse($turn[$f]);self::assertSame($turn,$service->perform($activation['activation_id'],$at->modify('+2 minutes')));}finally{$this->remove($root);}}
 public function testExpiredTurnCannotActivateProvider():void{$root=sys_get_temp_dir().'/imperium-citadel-turn-expired-'.bin2hex(random_bytes(5));try{[$decision,$authority,$locksmith]=$this->fixtures($root,'2026-08-23T20:00:00+00:00');$this->expectExceptionMessage('CLV305_PROVIDER_INVOCATION_ACTIVATION_CHAIN_INVALID');(new LegateProviderInvocationActivationService($root))->activate($decision,$authority,$locksmith,new \DateTimeImmutable('2026-08-23T20:00:00+00:00'));}finally{$this->remove($root);}}
 public function testOutputCannotClaimUndeclaredEvidence():void{$root=sys_get_temp_dir().'/imperium-citadel-turn-output-'.bin2hex(random_bytes(5));try{[$decision,$authority,$locksmith]=$this->fixtures($root,'2026-08-23T20:10:00+00:00');$at=new \DateTimeImmutable('2026-08-23T20:01:00+00:00');$activation=(new LegateProviderInvocationActivationService($root))->activate($decision,$authority,$locksmith,$at);$gateway=new class implements LegateCognitionGateway{public function cognize(array$a):array{return['disposition'=>'COMPLETED','output'=>'Unsupported.','evidence_references'=>['undeclared-source'],'uncertainties'=>[],'stop_condition_triggered'=>false,'stop_rationale'=>'Done.'];}};$this->expectExceptionMessage('CIT414_COGNITION_OUTPUT_CONTRACT_INVALID');(new LegateBoundedCognitionTurnService($root,$gateway))->perform($activation['activation_id'],$at->modify('+1 minute'));}finally{$this->remove($root);}}
 public function testInterruptedProviderCallCannotBeSilentlyInvokedAgain():void{$root=sys_get_temp_dir().'/imperium-citadel-turn-interrupted-'.bin2hex(random_bytes(5));try{[$decision,$authority,$locksmith]=$this->fixtures($root,'2026-08-23T20:10:00+00:00');$at=new \DateTimeImmutable('2026-08-23T20:01:00+00:00');$activation=(new LegateProviderInvocationActivationService($root))->activate($decision,$authority,$locksmith,$at);$gateway=new class implements LegateCognitionGateway{public function cognize(array$a):array{throw new \RuntimeException('provider interrupted');}};$service=new LegateBoundedCognitionTurnService($root,$gateway);try{$service->perform($activation['activation_id'],$at->modify('+1 minute'));self::fail('Expected interruption.');}catch(\RuntimeException$e){self::assertSame('provider interrupted',$e->getMessage());}$this->expectExceptionMessage('CIT418_PROVIDER_INVOCATION_ALREADY_CLAIMED');$service->perform($activation['activation_id'],$at->modify('+2 minutes'));}finally{$this->remove($root);}}
 private function fixtures(string$root,string$expires):array{$instance='imperium-test';$targetId='model-bound-operational-seat-binding-'.str_repeat('a',20);$target=$this->record(['schema'=>'imperium.model-bound-operational-manifestation-seat-binding/v1','binding_id'=>$targetId,'instance_id'=>$instance,'seat'=>'foundry.artificer','manifestation_id'=>'manifestation-artificer','occupancy_generation'=>1,'status'=>'ACTIVE','binding_atomic'=>true,'sealed'=>true]);$modelId='profile-model-binding-'.str_repeat('b',20);$profile=['model_binding'=>['provider_model_version'=>'deepseek/deepseek-v4-flash@2026-08-01','configuration'=>['temperature'=>0.2]]];$model=$this->record(['schema'=>'imperium.conscription-profile-model-binding/v1','binding_id'=>$modelId,'instance_id'=>$instance,'sealed_profile'=>$profile,'sealed'=>true]);$assertionId='clavium-provider-access-'.str_repeat('c',20);$assertion=$this->record(['schema'=>'imperium.clavium-provider-access-assertion/v1','assertion_id'=>$assertionId,'instance_id'=>$instance,'provider'=>'deepseek','credential_ref'=>'clavium://providers/deepseek/default','scope'=>['model.invoke'],'status'=>'ACCESS_AVAILABLE','revalidation'=>['expires_at'=>'2026-08-24T20:00:00+00:00'],'sealed'=>true],true);$attestationId='profile-model-access-attestation-'.str_repeat('d',20);$attestation=$this->record(['schema'=>'imperium.clavium-profile-model-access-attestation/v1','attestation_id'=>$attestationId,'instance_id'=>$instance,'model_binding'=>['binding_id'=>$modelId,'binding_digest'=>$model['record_digest'],'provider_model_version'=>'deepseek/deepseek-v4-flash@2026-08-01'],'provider_access_evidence'=>['assertion_id'=>$assertionId,'assertion_digest'=>$assertion['record_digest'],'provider'=>'deepseek','expires_at'=>'2026-08-24T20:00:00+00:00'],'status'=>'ACCESS_AVAILABLE','sealed'=>true]);$runtimeId='citadel-legate-runtime-activation-'.str_repeat('e',20);$runtime=$this->record(['schema'=>'imperium.conscription-citadel-legate-runtime-activation/v1','activation_id'=>$runtimeId,'instance_id'=>$instance,'source_model_binding'=>['id'=>$modelId,'digest'=>$model['record_digest']],'source_access_attestation'=>['id'=>$attestationId,'digest'=>$attestation['record_digest']],'runtime_active'=>true,'sealed'=>true]);$contract=['task'=>'Recommend.','purpose'=>'Answer.','inputs'=>['sealed-input-digest'],'evidence_requirements'=>['cite'],'constraints'=>['no tools'],'output_contract'=>['one answer'],'stop_conditions'=>['evidence absent']];$commissionId='citadel-legate-governed-commission-'.str_repeat('f',20);$dispositionId='citadel-legate-governed-commission-disposition-'.str_repeat('1',20);$turnAuthority='citadel-legate-cognition-turn-authority-'.str_repeat('2',20);$activationAuthority='citadel-legate-provider-invocation-activation-authority-'.str_repeat('3',20);$decisionId='citadel-legate-cognition-turn-authorization-decision-'.str_repeat('4',20);$decision=$this->record(['schema'=>'imperium.citadel-legate-cognition-turn-authorization-decision/v1','decision_id'=>$decisionId,'instance_id'=>$instance,'case_id'=>'case','case_digest'=>str_repeat('5',64),'source_commission_disposition'=>['id'=>$dispositionId,'digest'=>str_repeat('6',64)],'source_commission'=>['id'=>$commissionId,'digest'=>str_repeat('7',64)],'source_runtime_activation'=>['id'=>$runtimeId,'digest'=>$runtime['record_digest']],'source_access_attestation'=>['id'=>$attestationId,'digest'=>$attestation['record_digest']],'target'=>['seat'=>'foundry.artificer','binding_id'=>$targetId,'binding_digest'=>$target['record_digest'],'manifestation_id'=>'manifestation-artificer','occupancy_generation'=>1],'contract'=>$contract,'decision'=>'AUTHORIZED','expires_at'=>$expires,'status'=>'CITADEL_LEGATE_COGNITION_TURN_AUTHORIZED_PENDING_PROVIDER_INVOCATION_ACTIVATION','bounded_cognition_turn_authority'=>['authority_id'=>$turnAuthority,'authority_single_use'=>true,'destination'=>'foundry.artificer','purpose'=>'PERFORM_ONE_EXACT_GOVERNED_COGNITION_TURN','maximum_turns'=>1,'expires_at'=>$expires,'consumed'=>false],'governed_cognition_authority'=>true,'provider_invocation_activation_required'=>true,'provider_invocation_activation_authority'=>['authority_id'=>$activationAuthority,'authority_single_use'=>true,'destination'=>'clavium.locksmith','purpose'=>'ACTIVATE_ONE_EXACT_PROVIDER_INVOCATION','expires_at'=>$expires,'consumed'=>false],'provider_invocation_authority'=>false,'sealed'=>true]);$locksmithId='clavium-locksmith-binding-'.str_repeat('8',20);$locksmith=$this->record(['schema'=>'imperium.clavium-locksmith-occupancy/v1','binding_id'=>$locksmithId,'instance_id'=>$instance,'seat'=>'clavium.locksmith','manifestation_id'=>'manifestation-locksmith','occupancy_generation'=>1,'status'=>'ACTIVE','provider_invocation_activation_authority'=>true,'credential_disclosure_authority'=>false,'execution_authority'=>false,'sealed'=>true]);$this->write($root.'/var/imperium/operational/occupancy/'.$targetId.'.json',$target);$this->write($root.'/var/imperium/offices/conscription/profile-model-bindings/'.$modelId.'.json',$model);$this->write($root.'/var/imperium/offices/clavium/provider-access-assertions/'.$assertionId.'.json',$assertion);$this->write($root.'/var/imperium/offices/clavium/profile-model-access-attestations/'.$attestationId.'.json',$attestation);$this->write($root.'/var/imperium/operational/citadel-legate-runtime-activations/'.$runtimeId.'.json',$runtime);$this->write($root.'/var/imperium/operational/citadel-legate-cognition-turn-authorization-decisions/'.$decisionId.'.json',$decision);$this->write($root.'/var/imperium/offices/clavium/occupancy/'.$locksmithId.'.json',$locksmith);return[$decisionId,$activationAuthority,$locksmithId];}
 private function record(array$r,bool$prefixed=false):array{$r['record_digest']=($prefixed?'sha256:':'').hash('sha256',CanonicalJson::encode($r));return$r;}private function write(string$p,array$r):void{if(!is_dir(dirname($p)))mkdir(dirname($p),0770,true);file_put_contents($p,json_encode($r,JSON_THROW_ON_ERROR));}private function remove(string$p):void{if(!is_dir($p))return;foreach(array_diff(scandir($p)?:[],['.','..'])as$e){$c=$p.'/'.$e;is_dir($c)?$this->remove($c):unlink($c);}rmdir($p);}
